# qx_window :: ([1, 2, 3, 4, 5], 2)
def qx_window(xs, n):
    if n <= 0 or n > len(xs): return []
    return [xs[i:i+n] for i in range(len(xs) - n + 1)]

if __name__ == '__main__':
    print(qx_window(([1, 2, 3, 4, 5], 2)))

